import 'package:flutter/widgets.dart';

enum AirmiusLanguage { de, en, fr, ar }

extension AirmiusLanguageMeta on AirmiusLanguage {
  String get code => switch (this) {
    AirmiusLanguage.de => 'DE',
    AirmiusLanguage.en => 'EN',
    AirmiusLanguage.fr => 'FR',
    AirmiusLanguage.ar => 'AR',
  };

  String get label => switch (this) {
    AirmiusLanguage.de => 'Deutsch',
    AirmiusLanguage.en => 'English',
    AirmiusLanguage.fr => 'Français',
    AirmiusLanguage.ar => 'العربية',
  };

  bool get isRtl => this == AirmiusLanguage.ar;

  Locale get locale => switch (this) {
    AirmiusLanguage.de => const Locale('de'),
    AirmiusLanguage.en => const Locale('en'),
    AirmiusLanguage.fr => const Locale('fr'),
    AirmiusLanguage.ar => const Locale('ar'),
  };
}

class AirmiusScope extends InheritedWidget {
  const AirmiusScope({
    super.key,
    required this.language,
    required this.setLanguage,
    required super.child,
  });

  final AirmiusLanguage language;
  final ValueChanged<AirmiusLanguage> setLanguage;

  static AirmiusScope of(BuildContext context) {
    final scope = context.dependOnInheritedWidgetOfExactType<AirmiusScope>();
    assert(scope != null, 'AirmiusScope is missing');
    return scope!;
  }

  /// Resolves a translation without leaking German into another locale when
  /// that locale is still being completed. English is the neutral fallback,
  /// followed by German (the source language), and finally the key itself.
  ///
  /// Keeping this policy in one place makes newly added screens safe to ship:
  /// a missing French or Arabic entry remains readable instead of silently
  /// mixing an unrelated German sentence into the current page.
  String t(String key) {
    final localized = _strings[language]?[key];
    if (localized != null && localized.trim().isNotEmpty) return localized;

    if (language != AirmiusLanguage.en) {
      final english = _strings[AirmiusLanguage.en]?[key];
      if (english != null && english.trim().isNotEmpty) return english;
    }

    final german = _strings[AirmiusLanguage.de]?[key];
    if (german != null && german.trim().isNotEmpty) return german;
    return key;
  }

  /// Resolves a module label with the same locale fallback as [t].
  String copy(String value) {
    final localized = _copy[language]?[value];
    if (localized != null && localized.trim().isNotEmpty) return localized;
    if (language != AirmiusLanguage.de && language != AirmiusLanguage.en) {
      final english = _copy[AirmiusLanguage.en]?[value];
      if (english != null && english.trim().isNotEmpty) return english;
    }
    return value;
  }

  @override
  bool updateShouldNotify(AirmiusScope oldWidget) =>
      language != oldWidget.language;
}

/// Returns a localized message for errors that can occur before a screen has
/// access to an [AirmiusScope] (for example while the auth state is loading).
///
/// The auth layer only stores a locale code, so keeping this small resolver
/// here prevents it from duplicating translation tables or leaking a German
/// fallback into another selected language.
String airmiusAuthMessage(AirmiusLanguage language, String key, {int? status}) {
  final value =
      _strings[language]?[key] ??
      _strings[AirmiusLanguage.en]?[key] ??
      _strings[AirmiusLanguage.de]?[key] ??
      key;
  return status == null ? value : value.replaceAll('{status}', '$status');
}

